[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>WellSource — Expert health guidance you can trust</title>
<meta name="description" content="A comprehensive health and wellness media platform delivering medically reviewed content, tools, and resources to empower informed health decisions.">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet">
<style>
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --color-primary: #02838D;
  --color-primary-dark: #026B74;
  --color-primary-light: #E0F4F5;
  --color-secondary: #231F20;
  --color-coral: #E8734A;
  --color-coral-dark: #D4613A;
  --color-amber: #F5A623;
  --color-bg: #FFFFFF;
  --color-bg-warm: #FAFAF7;
  --color-bg-light: #F5F5F2;
  --color-bg-teal: #E8F6F7;
  --color-text: #1A1A1A;
  --color-text-secondary: #5A5A5A;
  --color-text-muted: #888888;
  --color-border: #E5E5E5;
  --color-border-light: #F0F0F0;
  --font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --max-width: 1240px;
  --radius: 12px;
  --radius-sm: 8px;
  --radius-lg: 16px;
  --shadow-sm: 0 1px 3px rgba(0,0,0,0.06);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.08);
  --shadow-lg: 0 8px 30px rgba(0,0,0,0.1);
  --transition: 200ms ease;
}

body {
  font-family: var(--font-family);
  color: var(--color-text);
  background: var(--color-bg);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

a { color: inherit; text-decoration: none; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }
img { max-width: 100%; display: block; }
ul { list-style: none; }

.container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }

/* ===== HEADER ===== */
.header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--color-bg);
  border-bottom: 1px solid var(--color-border);
}

.header-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 0;
  border-bottom: 1px solid var(--color-border-light);
}

.logo {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 24px;
  font-weight: 800;
  color: var(--color-primary);
  letter-spacing: -0.5px;
}

.logo svg { flex-shrink: 0; }

.header-actions {
  display: flex;
  align-items: center;
  gap: 20px;
}

.header-actions a {
  font-size: 14px;
  font-weight: 500;
  color: var(--color-text-secondary);
  transition: color var(--transition);
}

.header-actions a:hover { color: var(--color-primary); }

.btn-subscribe {
  background: var(--color-primary);
  color: #fff;
  padding: 8px 20px;
  border-radius: 100px;
  font-size: 14px;
  font-weight: 600;
  transition: background var(--transition);
}

.btn-subscribe:hover { background: var(--color-primary-dark); }

/* Main Nav */
.main-nav { position: relative; }

.nav-list {
  display: flex;
  align-items: center;
  gap: 0;
}

.nav-item { position: relative; }

.nav-link {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 14px 20px;
  font-size: 15px;
  font-weight: 500;
  color: var(--color-text);
  transition: color var(--transition);
  cursor: pointer;
}

.nav-link:hover, .nav-item.active .nav-link { color: var(--color-primary); }

.nav-link svg {
  width: 12px;
  height: 12px;
  transition: transform var(--transition);
}

.nav-item.active .nav-link svg { transform: rotate(180deg); }

/* Mega Menu */
.mega-menu {
  position: absolute;
  top: 100%;
  left: 0;
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-top: 3px solid var(--color-primary);
  border-radius: 0 0 var(--radius) var(--radius);
  box-shadow: var(--shadow-lg);
  padding: 28px 32px;
  min-width: 580px;
  opacity: 0;
  visibility: hidden;
  transform: translateY(8px);
  transition: all var(--transition);
  z-index: 200;
}

.nav-item.active .mega-menu {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}

.mega-menu-title {
  font-size: 13px;
  font-weight: 700;
  color: var(--color-primary);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  margin-bottom: 16px;
  padding-bottom: 10px;
  border-bottom: 1px solid var(--color-border-light);
}

.mega-menu-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 6px 24px;
}

.mega-menu-link {
  display: block;
  padding: 7px 10px;
  font-size: 14px;
  color: var(--color-text-secondary);
  border-radius: var(--radius-sm);
  transition: all var(--transition);
}

.mega-menu-link:hover {
  color: var(--color-primary);
  background: var(--color-primary-light);
}

/* Mobile menu toggle */
.mobile-menu-btn {
  display: none;
  padding: 8px;
  color: var(--color-text);
}

.mobile-menu-btn svg { width: 24px; height: 24px; }

/* ===== CREDIBILITY TICKER ===== */
.ticker-bar {
  background: var(--color-primary);
  color: #fff;
  overflow: hidden;
  position: relative;
  height: 44px;
}

.ticker-track {
  display: flex;
  align-items: center;
  height: 100%;
  animation: ticker-scroll 20s linear infinite;
  width: max-content;
}

.ticker-item {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 0 40px;
  font-size: 14px;
  font-weight: 500;
  white-space: nowrap;
}

.ticker-item svg { width: 18px; height: 18px; flex-shrink: 0; opacity: 0.85; }

.ticker-divider {
  width: 4px;
  height: 4px;
  background: rgba(255,255,255,0.4);
  border-radius: 50%;
  flex-shrink: 0;
}

@keyframes ticker-scroll {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

@media (prefers-reduced-motion: reduce) {
  .ticker-track { animation: none; }
}

/* ===== HERO ===== */
.hero {
  padding: 48px 0;
  background: var(--color-bg-warm);
}

.hero-grid {
  display: grid;
  grid-template-columns: 1fr 380px;
  gap: 48px;
  align-items: start;
}

.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: var(--color-coral);
  color: #fff;
  padding: 6px 14px;
  border-radius: 100px;
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  margin-bottom: 16px;
}

.hero-category {
  display: inline-block;
  color: var(--color-primary);
  font-size: 13px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  margin-bottom: 12px;
}

.hero-title {
  font-size: 40px;
  font-weight: 800;
  line-height: 1.15;
  color: var(--color-secondary);
  margin-bottom: 16px;
  letter-spacing: -0.5px;
}

.hero-subtitle {
  font-size: 18px;
  color: var(--color-text-secondary);
  line-height: 1.6;
  margin-bottom: 24px;
  max-width: 560px;
}

.hero-cta {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: var(--color-primary);
  color: #fff;
  padding: 14px 28px;
  border-radius: 100px;
  font-size: 15px;
  font-weight: 600;
  transition: background var(--transition);
}

.hero-cta:hover { background: var(--color-primary-dark); }

.hero-cta svg { width: 18px; height: 18px; }

.hero-image {
  width: 100%;
  aspect-ratio: 4/3;
  background: linear-gradient(135deg, var(--color-primary-light) 0%, #C7EAEC 50%, #A8D8DB 100%);
  border-radius: var(--radius-lg);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}

.hero-image-icon {
  width: 120px;
  height: 120px;
  background: rgba(255,255,255,0.6);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
}

.hero-image-icon svg { width: 60px; height: 60px; color: var(--color-primary); }

/* Trending sidebar */
.trending-sidebar { border-left: 3px solid var(--color-primary); padding-left: 24px; }

.trending-sidebar-title {
  font-size: 18px;
  font-weight: 700;
  margin-bottom: 20px;
  color: var(--color-secondary);
}

.trending-item {
  padding: 16px 0;
  border-bottom: 1px solid var(--color-border-light);
}

.trending-item:last-child { border-bottom: none; }

.trending-item-category {
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: var(--color-primary);
  margin-bottom: 6px;
}

.trending-item-title {
  font-size: 15px;
  font-weight: 600;
  line-height: 1.4;
  color: var(--color-secondary);
  transition: color var(--transition);
  cursor: pointer;
}

.trending-item-title:hover { color: var(--color-primary); }

/* ===== NEWSLETTER CTA ===== */
.newsletter-section {
  padding: 64px 0;
  background: linear-gradient(135deg, var(--color-primary) 0%, #03969F 100%);
  color: #fff;
  position: relative;
  overflow: hidden;
}

.newsletter-section::before {
  content: '';
  position: absolute;
  top: -60%;
  right: -10%;
  width: 500px;
  height: 500px;
  background: rgba(255,255,255,0.05);
  border-radius: 50%;
}

.newsletter-section::after {
  content: '';
  position: absolute;
  bottom: -40%;
  left: -5%;
  width: 400px;
  height: 400px;
  background: rgba(255,255,255,0.04);
  border-radius: 50%;
}

.newsletter-inner {
  text-align: center;
  max-width: 560px;
  margin: 0 auto;
  position: relative;
  z-index: 1;
}

.newsletter-icon {
  width: 56px;
  height: 56px;
  background: rgba(255,255,255,0.15);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 20px;
}

.newsletter-icon svg { width: 28px; height: 28px; }

.newsletter-title {
  font-size: 32px;
  font-weight: 800;
  margin-bottom: 12px;
  letter-spacing: -0.3px;
}

.newsletter-body {
  font-size: 16px;
  opacity: 0.9;
  margin-bottom: 28px;
  line-height: 1.7;
}

.newsletter-form {
  display: flex;
  gap: 12px;
  max-width: 460px;
  margin: 0 auto;
}

.newsletter-form input {
  flex: 1;
  padding: 14px 20px;
  border-radius: 100px;
  border: 2px solid rgba(255,255,255,0.3);
  background: rgba(255,255,255,0.12);
  color: #fff;
  font-size: 15px;
  font-family: var(--font-family);
  outline: none;
  transition: border-color var(--transition);
}

.newsletter-form input::placeholder { color: rgba(255,255,255,0.6); }
.newsletter-form input:focus { border-color: rgba(255,255,255,0.7); }

.newsletter-form button {
  background: var(--color-coral);
  color: #fff;
  padding: 14px 28px;
  border-radius: 100px;
  font-size: 15px;
  font-weight: 700;
  transition: background var(--transition);
  white-space: nowrap;
}

.newsletter-form button:hover { background: var(--color-coral-dark); }

.newsletter-privacy {
  font-size: 13px;
  opacity: 0.7;
  margin-top: 14px;
}

.newsletter-privacy svg { width: 14px; height: 14px; vertical-align: middle; margin-right: 4px; }

/* ===== HEALTH TOPICS ===== */
.health-topics {
  padding: 72px 0;
  background: var(--color-bg);
}

.section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 36px;
}

.section-title {
  font-size: 28px;
  font-weight: 800;
  color: var(--color-secondary);
  letter-spacing: -0.3px;
}

.section-link {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 15px;
  font-weight: 600;
  color: var(--color-primary);
  transition: gap var(--transition);
}

.section-link:hover { gap: 10px; }

.section-link svg { width: 16px; height: 16px; }

.carousel-wrapper { position: relative; }

.carousel-track {
  display: flex;
  gap: 28px;
  overflow-x: auto;
  scroll-behavior: smooth;
  scrollbar-width: none;
  padding: 8px 4px;
}

.carousel-track::-webkit-scrollbar { display: none; }

.topic-card {
  flex: 0 0 auto;
  width: 160px;
  text-align: center;
  cursor: pointer;
  transition: transform var(--transition);
}

.topic-card:hover { transform: translateY(-4px); }

.topic-image {
  width: 128px;
  height: 128px;
  border-radius: 50%;
  margin: 0 auto 14px;
  overflow: hidden;
  border: 3px solid var(--color-border-light);
  transition: border-color var(--transition);
}

.topic-card:hover .topic-image { border-color: var(--color-primary); }

.topic-image-inner {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  font-weight: 600;
  color: #fff;
}

.topic-name {
  font-size: 14px;
  font-weight: 600;
  color: var(--color-secondary);
}

.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-70%);
  width: 44px;
  height: 44px;
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: var(--shadow-md);
  transition: all var(--transition);
  z-index: 2;
}

.carousel-btn:hover {
  background: var(--color-primary);
  border-color: var(--color-primary);
  color: #fff;
}

.carousel-btn svg { width: 20px; height: 20px; }

.carousel-btn-prev { left: -22px; }
.carousel-btn-next { right: -22px; }

/* ===== TOOLS SECTION ===== */
.tools-section {
  padding: 72px 0;
  background: var(--color-bg-warm);
}

.tools-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 32px;
}

.tool-block {
  background: var(--color-bg);
  border-radius: var(--radius-lg);
  padding: 36px;
  border: 1px solid var(--color-border-light);
}

.tool-block-header {
  margin-bottom: 24px;
  padding-bottom: 20px;
  border-bottom: 1px solid var(--color-border-light);
}

.tool-block-icon {
  width: 48px;
  height: 48px;
  background: var(--color-primary-light);
  border-radius: var(--radius);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 16px;
  color: var(--color-primary);
}

.tool-block-icon svg { width: 24px; height: 24px; }

.tool-block-title {
  font-size: 22px;
  font-weight: 700;
  color: var(--color-secondary);
  margin-bottom: 8px;
}

.tool-block-desc {
  font-size: 14px;
  color: var(--color-text-secondary);
  line-height: 1.6;
}

.tool-block-cta {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 14px;
  font-weight: 600;
  color: var(--color-primary);
  margin-top: 12px;
  transition: gap var(--transition);
}

.tool-block-cta:hover { gap: 10px; }

.tool-list { display: flex; flex-direction: column; gap: 4px; }

.tool-item {
  display: flex;
  align-items: flex-start;
  gap: 14px;
  padding: 14px;
  border-radius: var(--radius-sm);
  transition: background var(--transition);
  cursor: pointer;
}

.tool-item:hover { background: var(--color-primary-light); }

.tool-item-icon {
  width: 40px;
  height: 40px;
  background: var(--color-bg-teal);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  color: var(--color-primary);
}

.tool-item-icon svg { width: 20px; height: 20px; }

.tool-item-name {
  font-size: 15px;
  font-weight: 600;
  color: var(--color-secondary);
  margin-bottom: 3px;
}

.tool-item-desc {
  font-size: 13px;
  color: var(--color-text-secondary);
  line-height: 1.5;
}

/* ===== RECOMMENDED READS ===== */
.recommended-reads {
  padding: 72px 0;
  background: var(--color-bg);
}

.tabs-container { margin-bottom: 36px; }

.tabs-list {
  display: flex;
  gap: 4px;
  border-bottom: 2px solid var(--color-border-light);
  overflow-x: auto;
  scrollbar-width: none;
}

.tabs-list::-webkit-scrollbar { display: none; }

.tab-btn {
  padding: 12px 20px;
  font-size: 14px;
  font-weight: 600;
  color: var(--color-text-muted);
  border-bottom: 3px solid transparent;
  margin-bottom: -2px;
  transition: all var(--transition);
  white-space: nowrap;
}

.tab-btn:hover { color: var(--color-text); }

.tab-btn.active {
  color: var(--color-primary);
  border-bottom-color: var(--color-primary);
}

.articles-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 28px;
}

.article-card {
  background: var(--color-bg);
  border-radius: var(--radius);
  overflow: hidden;
  border: 1px solid var(--color-border-light);
  transition: all var(--transition);
  cursor: pointer;
}

.article-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.article-card-image {
  width: 100%;
  aspect-ratio: 16/10;
  display: flex;
  align-items: center;
  justify-content: center;
}

.article-card-image svg { width: 40px; height: 40px; opacity: 0.3; }

.article-card-body { padding: 20px; }

.article-card-category {
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: var(--color-primary);
  margin-bottom: 8px;
}

.article-card-title {
  font-size: 17px;
  font-weight: 700;
  line-height: 1.35;
  color: var(--color-secondary);
  margin-bottom: 10px;
}

.article-card:hover .article-card-title { color: var(--color-primary); }

.article-card-meta {
  font-size: 13px;
  color: var(--color-text-muted);
}

/* ===== TRUST SECTION ===== */
.trust-section {
  padding: 80px 0;
  background: var(--color-bg-warm);
}

.trust-section .section-title { text-align: center; margin-bottom: 48px; }

.trust-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 32px;
}

.trust-card {
  text-align: center;
  padding: 36px 24px;
  background: var(--color-bg);
  border-radius: var(--radius-lg);
  border: 1px solid var(--color-border-light);
  transition: all var(--transition);
}

.trust-card:hover { box-shadow: var(--shadow-md); transform: translateY(-3px); }

.trust-icon {
  width: 64px;
  height: 64px;
  background: var(--color-primary-light);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 20px;
  color: var(--color-primary);
}

.trust-icon svg { width: 28px; height: 28px; }

.trust-card-title {
  font-size: 18px;
  font-weight: 700;
  color: var(--color-secondary);
  margin-bottom: 10px;
}

.trust-card-desc {
  font-size: 14px;
  color: var(--color-text-secondary);
  line-height: 1.6;
}

/* ===== FEATURED PROGRAMS ===== */
.featured-programs {
  padding: 72px 0;
  background: var(--color-bg);
}

.programs-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}

.program-card {
  border-radius: var(--radius);
  overflow: hidden;
  border: 1px solid var(--color-border-light);
  transition: all var(--transition);
  cursor: pointer;
}

.program-card:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); }

.program-card-image {
  width: 100%;
  aspect-ratio: 16/10;
  display: flex;
  align-items: center;
  justify-content: center;
}

.program-card-image svg { width: 36px; height: 36px; opacity: 0.3; }

.program-card-body { padding: 16px; }

.program-card-title {
  font-size: 15px;
  font-weight: 600;
  color: var(--color-secondary);
  line-height: 1.35;
}

.program-card:hover .program-card-title { color: var(--color-primary); }

/* ===== LATEST VIDEOS ===== */
.latest-videos {
  padding: 72px 0;
  background: var(--color-bg-warm);
}

.videos-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}

.video-card {
  border-radius: var(--radius);
  overflow: hidden;
  border: 1px solid var(--color-border-light);
  transition: all var(--transition);
  cursor: pointer;
  background: var(--color-bg);
}

.video-card:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); }

.video-card-thumb {
  width: 100%;
  aspect-ratio: 16/9;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
}

.play-btn {
  width: 52px;
  height: 52px;
