.footer-form input:focus { border-color: rgba(255,255,255,0.5); }

.footer-form button {
  background: var(--color-coral);
  color: #fff;
  padding: 12px 24px;
  border-radius: 100px;
  font-size: 14px;
  font-weight: 600;
  transition: background var(--transition);
  white-space: nowrap;
}

.footer-form button:hover { background: var(--color-coral-dark); }

.footer-links {
  display: flex;
  flex-wrap: wrap;
  gap: 12px 24px;
  align-content: flex-start;
}

.footer-links a {
  font-size: 14px;
  opacity: 0.75;
  transition: opacity var(--transition);
}

.footer-links a:hover { opacity: 1; }

.footer-bottom {
