<script>
(function() {
  // === MEGA MENU ===
  const navItems = document.querySelectorAll('.nav-item');

  navItems.forEach(item => {
    const btn = item.querySelector('.nav-link');
    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      const isActive = item.classList.contains('active');
      navItems.forEach(i => {
        i.classList.remove('active');
        const b = i.querySelector('.nav-link');
        if (b) b.setAttribute('aria-expanded', 'false');
      });
      if (!isActive) {
        item.classList.add('active');
        btn.setAttribute('aria-expanded', 'true');
      }
    });
  });

  document.addEventListener('click', () => {
    navItems.forEach(i => {
      i.classList.remove('active');
      const b = i.querySelector('.nav-link');
      if (b) b.setAttribute('aria-expanded', 'false');
    });
  });

  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') {
      navItems.forEach(i => {
        i.classList.remove('active');
        const b = i.querySelector('.nav-link');
        if (b) b.setAttribute('aria-expanded', 'false');
      });
    }
  });

  // === MOBILE MENU ===
  const mobileBtn = document.getElementById('mobileMenuBtn');
  const mainNav = document.getElementById('mainNav');

  mobileBtn.addEventListener('click', () => {
    mainNav.classList.toggle('mobile-open');
  });

  // === CAROUSEL ===
  const carousel = document.getElementById('topicsCarousel');
  const prevBtn = document.getElementById('carouselPrev');
  const nextBtn = document.getElementById('carouselNext');
  const scrollAmount = 200;

  prevBtn.addEventListener('click', () => {
    carousel.scrollBy({ left: -scrollAmount, behavior: 'smooth' });
  });

  nextBtn.addEventListener('click', () => {
    carousel.scrollBy({ left: scrollAmount, behavior: 'smooth' });
  });

  // === RECOMMENDED READS TABS ===
  const tabBtns = document.querySelectorAll('.tab-btn');
  const cards = document.querySelectorAll('.article-card');

  tabBtns.forEach(btn => {
    btn.addEventListener('click', () => {
      tabBtns.forEach(b => {
        b.classList.remove('active');
        b.setAttribute('aria-selected', 'false');
      });
      btn.classList.add('active');
      btn.setAttribute('aria-selected', 'true');

      const tab = btn.dataset.tab;

      cards.forEach(card => {
        const cats = card.dataset.categories.split(',');
        if (tab === 'top-reads' || cats.includes(tab)) {
          card.style.display = '';
          card.style.opacity = '0';
          card.style.transform = 'translateY(10px)';
          requestAnimationFrame(() => {
            card.style.transition = 'opacity 250ms ease, transform 250ms ease';
            card.style.opacity = '1';
            card.style.transform = 'translateY(0)';
          });
        } else {
          card.style.display = 'none';
        }
      });
    });
  });

  // === NEWSLETTER FORMS ===
  const newsletterForm = document.getElementById('newsletterForm');
  const footerForm = document.getElementById('footerForm');

  function handleSubmit(e) {
    e.preventDefault();
    const input = e.target.querySelector('input');
    const btn = e.target.querySelector('button');
    const originalText = btn.textContent;
    btn.textContent = 'Subscribed!';
    btn.style.background = '#059669';
    input.value = '';
    setTimeout(() => {
      btn.textContent = originalText;
      btn.style.background = '';
    }, 2500);
  }

  newsletterForm.addEventListener('submit', handleSubmit);
  footerForm.addEventListener('submit', handleSubmit);

  // === TICKER DUPLICATION ===
  const tickerTrack = document.getElementById('tickerTrack');
  const tickerContent = tickerTrack.innerHTML;
  tickerTrack.innerHTML = tickerContent + tickerContent;
})();
</script>
</body>
</html>
